    "bn15-11-minimal-m.top": {"id":"bn15-11-minimal-m.top","cat":"top","name":{"ko":"아이보리 골지 터틀넥","en":"Ivory ribbed turtleneck","de":"Elfenbeinfarbener Ripp-Rollkragenpullover"},"note":{"ko":"터틀넥의 골지 질감을 살리고 머플러는 느슨하게 둘러 목선을 정리하세요.","en":"Let the ribbed turtleneck show and wrap the scarf loosely around the neckline.","de":"Die Rippenstruktur sichtbar lassen und den Schal locker um den Rollkragen legen."},"image":"look/berlin-complete/Sunny/Chilly/Male/35+/night/11-minimal/products/02-top.jpg","bg":"#f2f0e9","alt":"아이보리 골지 터틀넥 단독 제품컷"},
