    "bd15-11-minimal-m.bottom": {"id":"bd15-11-minimal-m.bottom","cat":"bottom","name":{"ko":"블랙 플리츠 팬츠","en":"Black pleated trousers","de":"Schwarze Bundfaltenhose"},"note":{"ko":"바지통을 조이지 않고 자연스럽게 떨어뜨려요. 신발 윗부분이 드러나도록 밑단을 정돈해요.","en":"Let the legs fall naturally and keep the hem clear enough to show the shoes.","de":"Lasse die Hosenbeine locker fallen und ordne den Saum so, dass die Schuhe sichtbar bleiben."},"image":"look/berlin-complete/Sunny/Chilly/Male/35+/day/11-minimal/products/04-bottom.jpg","alt":"블랙 플리츠 팬츠 — 아이보리 배경의 단독 제품 컷","bg":"#F6F3EE"},
