    "bd15-11-minimal-f.08-earrings": {"id":"bd15-11-minimal-f.08-earrings","cat":"jewelry","name":{"ko":"미니 골드 스터드","en":"Mini Gold Studs","de":"Kleine goldfarbene Ohrstecker"},"note":{"ko":"작은 골드 톤 스터드로 마무리해요. 목걸이와 톤을 맞추고 크기는 작게 유지해요.","en":"Finish with tiny gold-tone studs, matching the necklace tone and keeping the scale small.","de":"Ergänze kleine goldfarbene Ohrstecker im Ton der Halskette."},"image":"look/berlin-complete/Sunny/Chilly/Female/35+/day/11-minimal/products/08-earrings.jpg","alt":"미니 골드 스터드 - 아이보리 배경의 개별 제품 컷","bg":"#F3F0EB"},
    "bd15-12-minimal-f.01-outer": {"id":"bd15-12-minimal-f.01-outer","cat":"outer","name":{"ko":"토프 테일러드 코트","en":"Taupe Tailored Coat","de":"Taupefarbener Mantel"},"note":{"ko":"앞을 열어 안쪽 레이어가 보이게 입어요. 소매와 밑단의 볼륨을 자연스럽게 남겨주세요.","en":"Wear it open to reveal the inner layers, keeping the natural volume of sleeves and hem.","de":"Trage die Jacke offen, damit die inneren Lagen sichtbar bleiben, und lasse Ärmeln und Saum ihr natürliches Volumen."},"image":"look/berlin-complete/Sunny/Chilly/Female/35+/day/12-minimal/products/01-outer.jpg","alt":"토프 테일러드 코트 - 아이보리 배경의 개별 제품 컷","bg":"#F5F0EA"},
    "bd15-12-minimal-f.02-top": {"id":"bd15-12-minimal-f.02-top","cat":"top","name":{"ko":"코발트 리브 니트","en":"Cobalt Rib Knit","de":"Kobaltblauer Rippstrickpullover"},"note":{"ko":"코발트 니트를 단독 컬러 포인트로 둬요. 코트를 열어 앞면의 선명한 블루가 드러나게 해요.","en":"Use cobalt knit as the single bold colour and open the coat to reveal its blue front.","de":"Setze mit Kobaltblau den einzigen kräftigen Farbakzent und öffne den Mantel darüber."},"image":"look/berlin-complete/Sunny/Chilly/Female/35+/day/12-minimal/products/02-top.jpg","alt":"코발트 리브 니트 - 아이보리 배경의 개별 제품 컷","bg":"#F6F2EA"},
    "bd15-12-minimal-f.03-bottom": {"id":"bd15-12-minimal-f.03-bottom","cat":"bottom","name":{"ko":"초콜릿 스트레이트 팬츠","en":"Chocolate Straight-Leg Trousers","de":"Schokoladenbraune gerade Hose"},"note":{"ko":"넉넉한 통을 접거나 조이지 않고 자연스럽게 떨어뜨려요. 상의 밑단을 정돈해 하의의 실루엣을 드러내요.","en":"Let the generous legs fall naturally and keep the top hem neat so the trouser shape stays visible.","de":"Lasse die weiten Beine natürlich fallen und ordne das Oberteil, damit die Form der Hose sichtbar bleibt."},"image":"look/berlin-complete/Sunny/Chilly/Female/35+/day/12-minimal/products/03-bottom.jpg","alt":"초콜릿 스트레이트 팬츠 - 아이보리 배경의 개별 제품 컷","bg":"#F7F2EC"},
    "bd15-12-minimal-f.04-socks": {"id":"bd15-12-minimal-f.04-socks","cat":"socks","name":{"ko":"브라운 리브 삭스","en":"Brown Rib Socks","de":"Braune Rippensocken"},"note":{"ko":"팬츠와 신발 사이에 리브 조직을 짧게 드러내요. 발목에 과하게 뭉치지 않게 정리해요.","en":"Show a short section of ribbing between trousers and shoes without excessive bunching.","de":"Zeige zwischen Hose und Schuhen etwas Rippstruktur, ohne die Socken stark zu stauchen."},"image":"look/berlin-complete/Sunny/Chilly/Female/35+/day/12-minimal/products/04-socks.jpg","alt":"브라운 리브 삭스 - 아이보리 배경의 개별 제품 컷","bg":"#F8F3ED"},
    "bd15-12-minimal-f.05-shoes": {"id":"bd15-12-minimal-f.05-shoes","cat":"shoes","name":{"ko":"다크 브라운 레이스업","en":"Dark Brown Lace-Ups","de":"Dunkelbraune Schnürschuhe"},"note":{"ko":"팬츠와 양말의 브라운을 레이스업까지 이어줘요. 끈은 단정하게 묶어 앞코의 매끈함을 살려요.","en":"Continue the brown of trousers and socks into lace-ups, tying them neatly to keep the toe clean.","de":"Führe die Brauntöne von Hose und Socken in Schnürschuhen fort und binde die Senkel ordentlich."},"image":"look/berlin-complete/Sunny/Chilly/Female/35+/day/12-minimal/products/05-shoes.jpg","alt":"다크 브라운 레이스업 - 아이보리 배경의 개별 제품 컷","bg":"#F6F2E9"},
    "bd15-12-minimal-f.06-jewelry": {"id":"bd15-12-minimal-f.06-jewelry","cat":"jewelry","name":{"ko":"골드 톤 코인 네크리스","en":"Gold-Tone Coin Necklace","de":"Goldfarbene Münzkette"},"note":{"ko":"니트 위로 작은 펜던트만 드러내요. 가는 체인으로 목선의 레이어를 가볍게 이어줘요.","en":"Let the small pendant sit over the knit, keeping the neckline light with a fine chain.","de":"Lasse den kleinen Anhänger über dem Strick liegen und halte den Ausschnitt mit einer feinen Kette leicht."},"image":"look/berlin-complete/Sunny/Chilly/Female/35+/day/12-minimal/products/06-jewelry.jpg","alt":"골드 톤 코인 네크리스 - 아이보리 배경의 개별 제품 컷","bg":"#F5F1EA"},
    "bd15-12-minimal-f.07-earrings": {"id":"bd15-12-minimal-f.07-earrings","cat":"jewelry","name":{"ko":"미니 골드 이어링","en":"Mini Gold Earrings","de":"Kleine goldfarbene Ohrringe"},"note":{"ko":"작은 후프로 얼굴 가까이에 은은한 포인트를 더해요. 목걸이와 비슷한 금속 톤으로 정리해요.","en":"Add a subtle accent near the face with small earrings, keeping the metal tone coordinated.","de":"Setze mit kleinen Ohrringen einen dezenten Akzent am Gesicht und stimme den Metallton ab."},"image":"look/berlin-complete/Sunny/Chilly/Female/35+/day/12-minimal/products/07-earrings.jpg","alt":"미니 골드 이어링 - 아이보리 배경의 개별 제품 컷","bg":"#F5F0EA"},
