    "bd15-13-minimal-f.02-top": {"id":"bd15-13-minimal-f.02-top","cat":"top","name":{"ko":"아이보리 터틀넥 니트","en":"Ivory Turtleneck Knit","de":"Elfenbeinfarbener Rollkragenpullover"},"note":{"ko":"터틀넥의 접힌 칼라를 정돈하고 머플러를 바깥으로 둘러요. 아이보리를 목과 커프에서 보여줘요.","en":"Set the folded turtleneck collar neatly beneath the scarf, showing ivory at neck and cuffs.","de":"Ordne den umgeschlagenen Rollkragen unter dem Schal und zeige Elfenbein an Hals und Bündchen."},"image":"look/berlin-complete/Sunny/Chilly/Female/35+/day/13-minimal/products/02-top.jpg","alt":"아이보리 터틀넥 니트 - 아이보리 배경의 개별 제품 컷","bg":"#F2ECE5"},
